{"task": "Find all log messages containing MAC addresses in colon format", "sql": "SELECT * FROM logs WHERE regexp_like(message, '([0-9a-fA-F]{2}[:]){5}[0-9a-fA-F]{2}')"}
{"task": "Count error logs that mention MAC addresses with hyphen separator", "sql": "SELECT COUNT(*) as mac_error_count FROM logs WHERE level = 'ERROR' AND regexp_like(message, '([0-9a-fA-F]{2}[-]){5}[0-9a-fA-F]{2}')"}
{"task": "Identify services with MAC address log entries and their message patterns", "sql": "SELECT service, message FROM logs WHERE regexp_like(message, '[0-9a-fA-F]{2}[:][0-9a-fA-F]{2}[:][0-9a-fA-F]{2}[:][0-9a-fA-F]{2}[:][0-9a-fA-F]{2}[:][0-9a-fA-F]{2}')"}
{"task": "Find log messages with MAC addresses and extract them using regexp_substr", "sql": "SELECT message, regexp_like(message, '[0-9a-fA-F]{2}[:-][0-9a-fA-F]{2}[:-][0-9a-fA-F]{2}[:-][0-9a-fA-F]{2}[:-][0-9a-fA-F]{2}[:-][0-9a-fA-F]{2}') as has_mac FROM logs"}
{"task": "List distinct services that have MAC address related log messages", "sql": "SELECT DISTINCT service FROM logs WHERE regexp_like(message, '[[:<:]]([0-9a-fA-F]{2}[:]){5}[0-9a-fA-F]{2}[[:>:]]')"}
{"task": "Find events where user paths contain MAC address patterns", "sql": "SELECT * FROM events WHERE regexp_like(path, '([0-9a-fA-F]{2}[:-]){5}[0-9a-fA-F]{2}')"}
{"task": "Count total log messages containing MAC addresses with different formats", "sql": "SELECT COUNT(*) as mac_count FROM logs WHERE regexp_like(message, '(^|\\s)([0-9a-fA-F]{2}[:]){5}[0-9a-fA-F]{2}(\\s|$)') OR regexp_like(message, '(^|\\s)([0-9a-fA-F]{4}\\.){2}[0-9a-fA-F]{4}(\\s|$)')"}
{"task": "Show log entries with MAC addresses and their timestamps", "sql": "SELECT ts, message FROM logs WHERE regexp_like(message, '(^|\\s)[[:xdigit:]]{2}[:-][[:xdigit:]]{2}[:-][[:xdigit:]]{2}[:-][[:xdigit:]]{2}[:-][[:xdigit:]]{2}[:-][[:xdigit:]]{2}(\\s|$)')"}
{"task": "Find error logs with MAC addresses in different case formats", "sql": "SELECT * FROM logs WHERE level = 'ERROR' AND regexp_like(message, '[0-9a-fA-F]{2}[:][0-9a-fA-F]{2}[:][0-9a-fA-F]{2}[:][0-9a-fA-F]{2}[:][0-9a-fA-F]{2}[:][0-9a-fA-F]{2}')"}
{"task": "Join events and logs to find MAC addresses in both tables", "sql": "SELECT e.id, l.message FROM events e JOIN logs l ON regexp_like(l.message, '[0-9a-fA-F]{2}[:-][0-9a-fA-F]{2}[:-][0-9a-fA-F]{2}[:-][0-9a-fA-F]{2}[:-][0-9a-fA-F]{2}[:-][0-9a-fA-F]{2}') WHERE regexp_like(e.path, '[0-9a-fA-F]{2}[:-][0-9a-fA-F]{2}[:-][0-9a-fA-F]{2}[:-][0-9a-fA-F]{2}[:-][0-9a-fA-F]{2}[:-][0-9a-fA-F]{2}')"}

